def fn(x):
    # Atbash cipher for lowercase letters
    res = []
    for ch in x:
        if 'a' <= ch <= 'z':
            # distance from 'a' is ord(ch) - ord('a')
            # mirror it around the alphabet: 25 - distance
            res.append(chr(ord('a') + 25 - (ord(ch) - ord('a'))))
        else:
            # leave other characters unchanged
            res.append(ch)
    return ''.join(res)

